WITH with_windows AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY amount DESC, id) AS event_seq, ROW_NUMBER() OVER (ORDER BY txn_time, id) AS seq_no, LAG(amount, 1) OVER (PARTITION BY account_id ORDER BY amount, id) AS prev_amount FROM transactions) SELECT id, amount, merchant, seq_no, prev_amount, CASE WHEN merchant RLIKE '^(Shell|Amazon)$' THEN 'GROUP_B' WHEN merchant RLIKE '^(Grab|7-Eleven)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS merchant_zone FROM with_windows
